export type GuideWorkbook = { goal: string; actions: string[]; example: string; check: string };
// Practical exercises are Guildframe recommendations. Examples are illustrative, not client results.
const entries: [string, string, string[], string, string][] = [
["board-game-kickstarter-funding-goal", "Check whether a fully funded project can deliver.", ["Check the base reward without stretch goals.", "Recalculate for the actual country and currency fee schedule.", "Include quantities bought but not yet sold.", "Record who will fund deposits before payout."], "Suppose your factory requires 1,000 copies but the campaign model includes only 500 pledged games. Record the full purchase commitment and the cash needed for unsold copies. If you expect retail sales to cover that gap later, name the financing available before those sales happen.", "At the exact funding target, the budget must cover the minimum purchase commitment and all promised rewards."],
["board-game-kickstarter-reward-pricing", "Approve the margin on each reward.", ["Compare the core and deluxe reward side by side.", "Check packed dimensions as well as product weight.", "Test bundles with the actual quantities and discounts.", "Apply your country's current Kickstarter fee rates to every tier."], "Compare a core box with a deluxe box that adds a playmat. Ask for the packed size of both. If the mat moves the parcel into a higher bracket, include that difference before choosing the upgrade price. Then check that a discounted bundle still leaves a margin after the extra handling.", "Reconcile the pricing sheet with the final reward contents and the fulfillment quotes."],
["kickstarter-referral-tags-tracking", "Build a link register you can audit.", ["Decide what each report is meant to answer", "Create named Kickstarter links before you publish the campaign", "Use one naming convention for your traffic links"], "Give a rules-preview email and a launch email separate placement names. Send test messages and copy the destination reached after clicking each one. Keep the actual Kickstarter-generated referral URL intact. This lets you trace an unexpected result back to a specific placement instead of guessing from a campaign total.", "Every live link should have a destination, owner, test date and named report."],
["board-game-reviewer-outreach", "Prepare a reviewer copy that is ready to play.", ["Choose reviewers by the games their audience plays", "Give the reviewer enough information to decide", "Make the request short and specific"], "Photograph the packed prototype and include the exact rules version. If a component is a placeholder, mark it in the brief so it is not mistaken for a final production sample. Ask the reviewer about timing before reserving space for their content in the campaign layout.", "Confirm receipt, resolve missing pieces and record permission before reproducing an excerpt."],
["board-game-kickstarter-launch-day-checklist", "Put a name beside every launch check.", ["Copy the 30 checks into your project plan.", "Name one owner for publishing, email, ads and support.", "Set the launch time and timezone with the whole team.", "Write down the approved daily ad cap."], "Keep the launch email ready while a second person checks the live campaign on a phone. If the deluxe reward shows the wrong contents, hold the announcement until the creator fixes the offer. Record the decision on the run sheet so ads and support follow the same plan.", "The campaign, the announcement and every ad should all lead to the same approved live offer."],
["board-game-pledge-manager-checklist", "Test the fulfillment export before choosing a system.", ["Confirm item and reward identifiers remain distinguishable.", "Check options and quantities after an upgrade.", "Verify shipping and payment states.", "Test address changes before the relevant lock deadline."], "Create a test order containing a base game, an expansion and a language selection. Change the destination country, then check the order summary and export. Compare the output with the warehouse import format, including quantities, paid status and the correct item identifiers.", "The fulfillment partner should be able to identify and process each test order without guessing."],
["choose-board-game-kickstarter-marketing-agency","Leave the sales call with a proposal you can compare.",["Send the same deliverables list to each agency.","Separate service fees, media spend and any revenue share.","Ask who owns the ad account, contacts and editable files."],"Suppose one quote includes a landing page and six emails while another covers only campaign graphics. Put the missing work beside each total before comparing prices. Ask each agency to identify the person who checks reward facts and approves publication.","A proposal is ready to compare when the work, dates, approval rules and handover files are named."],
["kickstarter-prelaunch-page-vs-landing-page","Choose where each visitor should go before launch.",["Give cold traffic one clear explanation and signup action.","Invite interested subscribers to follow the platform page.","Measure signups and platform follows separately."],"A new visitor from a gameplay clip may need a playable example before sharing an email. Someone already reading your newsletter may only need the Kickstarter follow link. Keep those paths distinct so you can diagnose a weak ad without blaming the platform page.","Follow both paths on a phone and check what the visitor sees after completing the action."],
["board-game-kickstarter-marketing-plan", "Turn a launch date into a weekly plan with owners.", ["List the open product, reward and shipping decisions.", "Give each channel an owner and an output.", "Review audience evidence before committing the launch budget."], "For a cooperative card game, one week might produce a filmed sample turn, a landing page test and a welcome email. If visitors sign up but cannot say what the box contains, spend the next week fixing the offer before buying more traffic. A schedule should change when the evidence changes.", "Every scheduled task should produce something you can review, such as a file, a tested flow, a quote or a decision."],
["kickstarter-prelaunch-email-list","Build a list whose subscribers understand the game.",["State what people are signing up to receive.","Test the form, contact record and welcome message.","Segment existing fans from new paid traffic."],"Use a welcome email to explain one appealing decision in the game and link to the rules or a sample turn. A reply asking whether the reward is a physical deck or a PDF exposes a message problem you can fix before launch. Track replies alongside clicks; open rates alone do not show purchase intent.","Subscribe with a fresh address, confirm the right message arrives and test the unsubscribe route."],
["kickstarter-advertising-budget-board-games","Set a spending limit that your reward economics can support.",["Calculate contribution after production and delivery obligations.","Separate a learning budget from a scaling budget.","Set a review date and stop condition before spending."],"If a hypothetical reward leaves $12 after non-ad costs and your reserve, a $10 acquisition cost leaves only $2. A higher-priced bundle may produce more revenue while leaving less contribution. Compare the actual reward mix before increasing a budget because reported return on ad spend looks strong.","The budget sheet should show service fees, media spend, attribution limits and the person who can approve an increase."],
["kickstarter-live-campaign-updates","Answer backer questions without making unapproved promises.",["Keep one queue of recurring questions.","Confirm production facts with the responsible supplier or owner.","Record which public pages need the same correction."],"If a backer asks whether a tray fits sleeved cards, get a measured answer before adding it to an update. If the fit is still being tested, say so. Once confirmed, update the reward description and FAQ too; otherwise the campaign will contain conflicting answers.","A useful update tells backers what changed, what it affects and when the next confirmed information is expected."],
["kickstarter-prelaunch-page-guide","Give a follower enough information to recognize the project at launch.",["Show the product and its central play experience.","Check the public page separately from the private preview.","Use the same game name and visual identity in email."],"A title, dramatic illustration and vague promise can attract curiosity without explaining the game. Add a short line about player decisions and the intended audience. When the launch email arrives, the person should recognize the same product rather than wonder which signup it came from.","Ask an unfamiliar reader to describe the product after seeing only the public prelaunch page."],
["board-game-kickstarter-gameplay-rulebook","Make one complete turn understandable before asking for a pledge.",["Show the starting position and the player's options.","Explain a choice and its consequence.","Link the current rules with a visible version date."],"For a set-collection game, show a hand, the cards available to take and the scoring change after a choice. An exploded component image cannot substitute for that explanation. Keep unusual terms beside their definitions so the example does not require reading the entire rulebook first.","A reader should be able to describe why they would choose one action over another."],
["kickstarter-campaign-video-planning","Brief a video around the product decisions viewers need to understand.",["Write the game promise before the shot list.","Capture real components and a representative turn.","Prepare captions and a clean thumbnail."],"A draft shot list can pair the spoken line about cooperation with a visible shared decision, rather than another box rotation. Watch the rough cut muted on a phone. If the core idea disappears, captions or clearer visual sequencing may do more than extra effects.","Check every product shot against the current reward contents and label prototype material where needed."],
["kickstarter-stretch-goals-planning","Approve each extra before turning it into a public promise.",["Price the added unit cost at realistic quantities.","Check tooling, weight and packing changes.","State exactly which rewards receive the extra."],"A thicker token may look like a small upgrade but change the insert, box height and packed weight. Ask the manufacturer and fulfillment partner to price the whole change. A goal is not ready simply because the print cost fits inside the additional funding.","Keep an approval record for cost, timing, eligible rewards and any effect on existing backers."],
["kickstarter-shipping-delivery-page","Give backers a clear account of when and how delivery charges are collected.",["Separate manufacturing, freight, fulfillment and final delivery.","Label regional figures as estimates where appropriate.","State how taxes and import charges are handled."],"A reward table that says shipping is separate needs a nearby explanation of when it will be charged. Show the planned region list and the assumptions behind estimates, such as one core game per parcel. A bundle can change the parcel size enough to need its own estimate.","Read the page as a buyer in your most expensive supported region and identify every payment they may face."],
["kickstarter-prototype-risks-disclosure","Show what exists and what still needs work.",["Label renders, prototypes and production samples accurately.","List unresolved production dependencies.","Give each risk a next verification step."],"A painted render and a resin test print answer different questions. Put the label beside the image and explain what the print test established, such as scale or fit. Do not imply that testing one component proves the final factory production run is ready.","Every production claim should have an owner and evidence that matches the claim's scope."],
["kickstarter-review-launch-timeline","Keep platform review separate from creative approval.",["Identify the last facts needed for a complete submission.","Allow time for requested changes and resubmission.","Confirm approval before promising a public launch time."],"A finished hero graphic does not settle identity checks, reward setup or the production plan. Work backwards from the intended date and give each dependency its own owner. Keep promotional bookings flexible until the project is ready to publish.","The launch calendar should include a fallback date and the people who need to know if the date changes."],
["gamefound-launch-page-checklist","Test the project in the stage your audience will actually use.",["Review the project as a backer, not only inside the editor.","Check reward variants and add-on combinations.","Test which shipping details and charges are collected in each stage."],"A page copied from a campaign stage may describe delivery collection that happens later. Review the full order route, including the summary and confirmation. Use Gamefound's testing facilities for supported scenarios and record the stage used in each test.","Keep a test order matrix covering a core reward, a bundle, an add-on and representative delivery regions."],
["card-game-kickstarter-launch-guide","Explain what someone can play with the reward they choose.",["State player count and the decks needed to start.","Distinguish fixed contents from random assortments.","Show card text at a readable size."],"If a starter box supports two players while a booster cannot be played alone, say so next to the reward. For collectible products, distinguish the cards shown for illustration from any guaranteed contents. A buyer should not need to infer the format from a dramatic spread of cards.","Ask a new player to pick the smallest reward that lets their group play."],
["miniatures-stl-kickstarter-launch-guide","Keep digital files, physical models and license terms separate.",["Label each reward as physical, digital or mixed.","Show scale and what the test prints demonstrate.","Explain permitted use and delivery format."],"A terrain render can suggest a complete table while the reward contains only a small file pack. List the included pieces and show a scale reference. If supports or commercial permissions are separate, make those distinctions visible before a buyer chooses a reward.","Review the reward without looking at its images: the written contents should still explain exactly what is delivered."],
["board-game-kickstarter-campaign-design-cost","Compare design proposals against the same file list.",["Count the sections and reward comparisons you need.","Identify missing art, photography and copy.","Agree review rounds and editable-file delivery."],"A campaign with two editions and one add-on needs a different reward presentation from a game with multiple languages, bundles and upgrades. Send the actual reward matrix with the brief. Otherwise a low initial quote can reflect an incomplete view of the work.","Check the quoted scope against a section-by-section page outline before booking."],
["board-game-kickstarter-page-checklist","Find the questions an unfamiliar backer cannot answer.",["Check the game explanation before the decorative sections.","Compare the page's reward contents with platform settings.","Read the complete page at phone width."],"Ask a tester to find the player count, explain a turn and choose a reward within a few minutes. Record where they hesitate without prompting them. If several testers miss shipping information, move or rewrite that information instead of adding another decorative section.","Repeat the task after revisions with someone who has not seen the earlier version."],
["what-to-send-kickstarter-campaign-designer","Prepare one approved source of product facts.",["Separate approved assets from drafts.","Write reward names, contents and prices in one sheet.","Name the person who approves factual changes."],"Use filenames that distinguish prototype, final and reference art. Include a short note explaining which images may be cropped and which show dimensions that must stay legible. A designer can build the page faster when they are not reconciling conflicting reward lists from messages.","Someone outside the project should be able to locate the latest logo, rules, reward sheet and delivery assumptions."],
["kickstarter-reward-tier-graphics","Help a backer see what changes between tiers.",["Keep common contents aligned in the comparison.","Call out the added items rather than repeating every label.","Match names and prices to platform settings."],"If the deluxe tier adds metal coins and a playmat, show those additions together while keeping the core game in the same position. Avoid using a larger box image as the only signal of value. State whether the picture includes optional extras or items supplied separately.","Check that the written reward list and the graphic can be understood independently."],
["ttrpg-kickstarter-campaign-page-design","Explain what a group needs to use the book or files.",["State the system and any required books.","Show readable sample pages and a session premise.","Separate PDF, print and accessory rewards."],"A campaign for an adventure should identify whether it is a complete game or needs another ruleset. Show a useful spread, such as a location and encounter, instead of only cover art. If the print tier also includes a PDF, state when each format is expected to arrive.","Ask a game master what they would need to bring to run the first session."],
["kickstarter-vs-gamefound-campaign-page-design","Adapt the buyer's route to the platform you choose.",["List the stages and tools the project will use.","Rebuild reward comparisons for the chosen editor.","Test the final page and order route on mobile."],"Moving artwork between platforms does not automatically carry over reward selection, follow actions or later shipping collection. Start with the backer journey and note where each fact needs to appear. Keep essential product information in readable page text as well as graphics.","Confirm the published page, not just the source files, against the intended launch stage."],
["kickstarter-campaign-graphics-mobile-readability","Make essential reward facts readable without zooming.",["Keep product specifications in page text.","Break wide comparison sheets into narrower sections.","Test image text on a small phone."],"A six-column reward matrix may look fine on a design monitor but become illegible when scaled to a phone. Split it by edition or compare only the differences. Use short labels and put the complete contents in nearby text so the image is not the only usable version.","Check at actual display width and ordinary brightness, without pinching to enlarge."],
["when-to-hire-kickstarter-campaign-designer","Book around decisions that are ready and decisions still changing.",["Prepare a clear game summary and representative assets.","Identify reward and production decisions still open.","Agree a date for freezing the first full layout."],"You can explore an opening design while later sections remain incomplete. Tell the designer which facts may change, especially reward names, box contents and delivery estimates. A late change to the reward structure can affect many graphics, so schedule that decision before final export.","The schedule should allow the creator to review facts and the designer to check the assembled page."],
["what-happens-after-kickstarter-is-funded","Separate money collected, promises made and work still to deliver.",["Reconcile collected pledges and unresolved payments.","Confirm quantities before placing production orders.","Set the next backer update and support owner."],"A funding total is not the same as the cash available for production. Prepare a reconciliation that separates expected funds, fees, failed payments and costs already incurred. Keep late orders visible in the quantity plan so they do not silently consume stock intended for backers.","Every outstanding promise should have an owner, next step and date for the next update."],
["move-from-kickstarter-to-shopify","Build a store without losing the campaign's delivery obligations.",["Map rewards to retail products and variants.","Keep backer orders separate from new retail orders.","Plan redirects and content reuse before launch."],"A campaign bundle may contain a limited extra that will not be sold at retail. Create a product map before importing descriptions. Mark which images need new captions and which availability claims no longer apply. Importing all campaign language unchanged can create promises the store cannot fulfil.","Place a test order for a new customer and check that it cannot consume reserved backer inventory."],
["best-shopify-themes-for-board-games","Choose a theme using your real catalog and buying tasks.",["Load representative product photos into a trial.","Test variants, compatibility notes and mobile navigation.","List required apps and customization work before buying."],"Test a core game with an expansion, a long rules description and several product images. A theme that looks attractive with a single poster image may struggle with compatibility information. Compare the total setup work and ongoing app costs alongside the theme's license price.","Use the same products and tasks in every trial so the comparison is meaningful."],
["shopify-developer-vs-diy-theme","Assign the work to the person who can maintain it.",["List catalog, design and integration needs.","Estimate the hours available for setup and testing.","Agree ownership, documentation and maintenance."],"A small catalog with standard shipping can be manageable in a theme editor. A store that combines preorders, region rules and bundles may need deeper implementation and testing. Ask for a handover that lets the owner update products without depending on a developer for every edit.","Compare the full setup and maintenance workload, including the tasks left with you after launch."],
["kickstarter-late-pledges-vs-shopify","Choose an order channel that matches the stage of delivery.",["Identify whether you are still managing backer rewards.","Decide where shipping details and charges belong.","Define when stock becomes available for retail."],"If production quantities are still open, a late-pledge route may fit the campaign workflow. Once fulfillment and retail inventory are separated, a permanent store may be easier to operate. Avoid taking the same customer's payment twice when moving between pledge collection and shipping collection.","Write down which system owns each order, address, payment and customer-support record."],
["backerkit-vs-shopify-vs-gamefound","Compare platforms by the job they must do now.",["Separate crowdfunding, pledge management and retail.","Check current features in the intended account and region.","Compare exports, fees and support responsibilities."],"A platform can support several stages without making every stage identical. Test a new customer's order and an existing backer's completion separately. Ask how you export product selections, addresses, collected shipping and taxes, then compare that export with the fulfillment partner's requirements.","A feature list is useful only when it covers the order routes your project needs."],
["kickstarter-to-shopify-launch-timeline","Launch retail when inventory and customer promises are ready.",["Map backer obligations before planning stock availability.","Prepare products and policies while fulfillment work continues.","Run complete test orders before announcing the store."],"The store can be built before every parcel ships, but public availability should reflect the stock you can actually sell. If a product is a preorder, show its expected timing separately from in-stock products and explain what happens to mixed orders.","Confirm the support, inventory and fulfillment owners all agree the store is ready."],
["sell-board-game-preorders-on-shopify","Make the order's timing and payment terms clear.",["Label preorders near the purchase action.","Explain payment timing and cancellation terms.","Test mixed carts and delayed fulfillment messages."],"If a customer buys an in-stock card deck and a preorder expansion, decide whether the order ships together or separately. State that decision before checkout. Test the confirmation message so it does not imply immediate dispatch for an item that is still in production.","A customer should be able to find the expected delivery window and contact route after checkout."],
["sell-board-game-expansions-add-ons-shopify","Help customers buy compatible products.",["State which base game or edition an expansion requires.","Separate product variants from additional products.","Check stock accounting for bundles."],"An expansion that requires the second edition should say so beside the purchase controls and in the description. When a bundle sells, confirm that the underlying stock is adjusted correctly. Otherwise the store can continue selling a component already allocated to a bundle.","Test a compatible combination, an incompatible combination and an out-of-stock component."],
["selling-miniatures-internationally-vat-ioss","Prepare the facts a customs or tax adviser needs.",["Record dispatch country, destination and goods value.","Confirm classifications, origin and packed dimensions.","Test the agreed duty and tax treatment at checkout."],"A parcel containing different products can need more than one customs classification. Record actual contents rather than a broad label such as gaming accessories. Ask the carrier how it transmits the required data and how any IOSS arrangement is applied to eligible orders.","Keep a dated record of the advice and carrier setup. Recheck rules before opening a new market."],
["how-much-does-a-board-game-website-cost","Budget the first year as well as the initial build.",["List platform, theme, apps and implementation separately.","Include catalog preparation and payment testing.","Estimate support and maintenance after launch."],"A lower build quote can leave product entry, policy writing and integrations to the owner. Compare proposals using the same catalog size and features. Record recurring charges in their billing currency and verify current regional pricing before choosing a plan.","Ask what the first year costs if the store launches with the agreed scope and ordinary maintenance."],
["shopify-vs-etsy-for-selling-miniatures","Compare discovery and operating costs for the products you sell.",["Separate marketplace discovery from traffic you bring yourself.","Model the fees on a representative order.","Check license terms and marketplace eligibility."],"For a physical terrain kit, include packaging, payment processing and any applicable advertising charges in the comparison. For digital files, check the platform's rules for the actual product and your rights to sell it. A cheaper headline fee does not show the total cost of acquiring an order.","Use the same product price, delivery region and order assumptions for both channels."],
["build-a-tabletop-shopify-store-with-ai","Use AI assistance where you can verify the result.",["Write product and inventory rules before generating code.","Review changes in a preview theme.","Test checkout, variants and accessibility with real data."],"A generated product section may look correct while linking an expansion to the wrong edition. Keep a small set of representative products and repeat the same purchase tasks after each change. Preserve a rollback version before publishing theme edits.","A successful preview is not proof of payment, order routing or recipient delivery; test those outcomes separately."],
["kickstarter-fees","Put every Kickstarter fee into your budget sheet before you set the goal.",["Write down your expected average pledge and backer count.","Check your country's processing rate on Kickstarter's fee page.","Work out the fees on each reward tier, including PDF and $1 tiers.","Add fee lines for late pledges and pledge manager payments.","Divide what you need after fees by the share you keep."],"Hypothetical example: you need $30,000 after fees and expect a $40 average pledge on a US project. Each $40 pledge loses $3.40, so you keep 91.5 cents of every dollar. Dividing $30,000 by 0.915 gives a goal of about $32,800, before you leave room for pledges that fail to collect.","Change one reward price in your sheet and confirm the fees, the payout and the goal all update with it."],
["kickstarter-agency-cost","Turn every agency proposal into one total you can compare.",["Send each agency the same scope list of pages, emails, graphics, ads and live campaign work.","Ask for the total cost at a low, middle and high pledge figure.","Add the same ad budget and platform fees to every proposal.","Ask in writing how commission pledges are attributed.","Confirm who owns the files, ad accounts and email list at the end."],"Hypothetical example: one agency quotes a fixed fee and another asks for a share of pledges. Estimate your pledge total at three levels and multiply the commission out at each one. If the commission passes the fixed fee at your middle figure, you can see where the cheaper looking offer stops being cheaper.","Each proposal should show its scope, its total at three pledge levels and the costs it leaves to you, side by side on one page."],
["kickstarter-vs-gamefound","Choose a platform from your own backers, not from the headline fee.",["List where your current followers and subscribers already back projects.","Model 5% plus processing on your real reward prices for both platforms.","Pick an ad route: Adfound, Jellop or your own Meta ads.","Ask your fulfillment partner which pledge manager exports they can import.","Decide whether you will sell add ons and late pledges after funding."],"Hypothetical example: you ask your 600 email subscribers where they usually back games, and most of them name Gamefound. Your party card game could reach a wider crowd on Kickstarter, but your known backers point the other way. Record the answers and the reason for your pick, so the decision rests on evidence you can show.","Answer every question in the guide's checklist with a fact from your own list, prices or fulfillment plan, not a guess."],
["pledge-managers-compared","Test your messiest order in each pledge manager you shortlist.",["Write down your most complicated order, with edition, language, add ons and destination.","Note where you funded, because that narrows the tools before fees do.","Estimate survey spend on add ons and shipping, then apply each published fee.","Ask each vendor for any processing figure its pricing page leaves out.","Compare each tool's order export with your warehouse import format."],"Hypothetical example: backers are expected to spend $10,000 on add ons and shipping in the survey. A 3% fee costs $300 and a 5% fee costs $500, before processing. Then build a test order with a base game, an expansion and a language choice, change the country, and check the export your warehouse would receive.","Your fulfillment partner should be able to read the test export without asking what any code or paid status means."],
["kickstarter-image-sizes","Build your export list and test one section before you make the rest.",["Copy the cheat sheet rows for your platform into an export list.","Plan the crops your artwork needs, such as 16:9 for Kickstarter or a square and a 21:6 strip for Gamefound.","Export one story graphic and one reward image at the sizes in the table.","Upload both to the draft and check the preview on a phone.","Decide on the main video and the vertical clip before anyone films."],"Hypothetical example: you export a story graphic at 1400 pixels wide and a reward image at 1200 × 800 for Kickstarter. In the phone preview the reward image reads well, but small text in the story graphic blurs after compression. You fix the text size now, while one file needs changing instead of forty.","Every file on the export list should meet or beat the published minimum, and the test section should read on a phone without zooming."],
["board-game-tariffs-shipping-us","Put a dated tariff line, confirmed by your broker, into each US reward price.",["List each reward's contents with the country where each item is made.","Ask your customs broker for the HTS code and full duty rate on each item.","Add the duty to your landed cost before reward prices are final.","Decide whether US duty sits in the reward price, the shipping charge or a Tariff Manager surcharge.","Write a dated tariff note for the shipping section of your page."],"Hypothetical example: a game costs $12 a copy at a factory in China, and duty is charged on that $12. The 12.5% Section 301 rate alone adds $1.50 a copy. Your broker may find other duties on top, so the reward price uses the broker's full figure rather than this one rate.","Your page, pledge manager and backer updates should all give US backers the same tariff answer, with the date it was checked."],
["kickstarter-followers-before-launch","Turn your funding goal into a follower target you can track every week.",["Divide your funding goal by your expected average pledge to get a backer target.","Divide that backer target by 10%, by 20 to 25% and by 32% to get three scenarios.","List where your current followers came from, warmest source first.","Record your follower and email counts on the same day each week.","Two weeks before launch, check whether the low case covers the goal."],"Hypothetical example: a card game has a $15,000 goal and an expected $50 average pledge, so it needs 300 backers. At 10% that means 3,000 followers, at 20 to 25% it means 1,200 to 1,500, and at 32% about 940. If you have 900 followers two weeks out, moving the date may cost less than a slow first day.","Your plan should fund in the low case from followers and your own email list, with platform traffic and ads left as extra."],
["ttrpg-kickstarter-launch-guide","Lock your RPG's launch window and delivery route before you design rewards.",["Choose Zine Quest, Zinetopia or your own date, and note any application deadline.","Decide how backers will get their PDFs, and who sends the files and when.","Publish a free quickstart, one shot or sample spread that links to your prelaunch page.","Write down the system, any books a group needs and what one session looks like.","Select the tabletop roleplaying subcategory and check it again before review."],"Hypothetical example: you are launching a short zine and want Zinetopia. That means applying by January 4, 2027, launching and ending between February 2 and 19, and running and fulfilling on BackerKit. If your readers mostly back on Kickstarter instead, your own date with a longer prelaunch may suit the zine better.","A game master who reads only your page and rewards should know what to bring to the first session and when each format arrives."],
["terrain-and-dice-kickstarter-launch-guide","Answer size, fit and contents for every reward before you write the page.",["Measure every product and put the confirmed dimensions beside its image.","Photograph each set as separate parts and as two or three builds.","Label every image as a render, test print, painted sample or production piece.","Decide which rewards are physical, which are STL files and which add ons each can take.","Get the packed box size for every reward and likely bundle."],"Hypothetical example: a terrain set packs into a 16 × 12 × 6 inch box. At UPS daily rates that is 1,152 cubic inches divided by 139, which rounds up to 9 pounds of dimensional weight, even if the box weighs 3 pounds. Ask your fulfillment partner to quote that packed box, then price shipping from their figure.","Cover the images and read only the reward text: it should still say what arrives, how big it is and what it builds."],
["tcg-kickstarter-launch-guide","Settle collation, print minimums and reward limits with your printer first.",["Name the smallest reward that lets two people start playing.","Ask your printer in writing how it randomizes boosters and whether it supports rarities.","Ask how your card count lays out on its press sheets and what the minimum order is.","Put booster boxes in fixed tiers and set a quantity limit on the most sought after tier.","Write every pack description from the printer's confirmed specification."],"Hypothetical example: you plan 100 card designs in commons, uncommons and rares. PrintNinja says it randomizes only on orders above 20,000 units and does not offer rarities, so a page printed there could not promise rare cards. A printer with rarity tiers and drop rates, as QP Market Network describes, changes what your booster copy can say.","Every rarity or pack claim on the page should match a line in the printer's written specification, and go no further."],
["how-to-market-a-kickstarter","Write your player sentence and set a weekly marketing habit you can keep.",["Describe your player in one sentence and list three games they already own.","Set up your prelaunch page, a reason to follow and an email signup.","Pick two or three channels that suit your player and read each community's rules.","Each week, post one thing that shows the game and note where new followers came from.","Hold paid ads until the landing page turns visitors into followers."],"Hypothetical example: your player sentence is people who love quick card games they can teach in five minutes. The games on their shelves point you to two card game subreddits and a local game night, so those become your channels. Each week you post one short clip of a turn, invite viewers to the prelaunch page and note which channel each new follower came from.","Add up what friends, family, followers and your email list could pledge on day one, then compare it with 30% of your goal."],
["how-to-get-kickstarter-backers","List your first hundred people, ring by ring, and give each one a place to follow.",["Write down everyone who has played your game, with how to reach them.","Add the local game stores and game nights where you can run a demo.","Join three communities where your players talk, and read their self promotion rules.","Have your prelaunch page, email signup and one thing to show ready before you ask.","Ask each person to follow, join the list and name one friend who would enjoy the game."],"Hypothetical example: with a $50 average pledge, 100 backers cover a $5,000 goal. You count 25 playtesters, 15 friends and family and 30 people from two store demos. That leaves 30 people to find through communities, reviewers or a small ad test, so you know where the next month of effort goes.","Every name on the list should have a ring, the date you asked and whether they followed the page or joined the email list."],
["how-to-design-a-kickstarter-page","Outline your page around the four questions a backer asks.",["Write one line each for what the game is, how it plays, what backers get and why they can trust you.","Draft the top: project image, title, a subtitle for a stranger and the table facts.","Pick one turn to show, with what a player sees, chooses and what happens next.","List every reward with labeled contents, counts and prices in one place.","Set two fonts, colors taken from the box art and a minimum text size for phones."],"Hypothetical example: a tester reads your draft on a phone and reaches the stretch goals before learning how a turn works. They also find the deluxe price in one section and its contents in another. You move the sample turn above the stretch goals and put each reward's price beside its contents, then test again with someone new.","Hand a phone to someone who hasn't played the game: they should explain a turn and pick a reward without asking you anything."],
["is-my-game-ready-for-kickstarter","Answer the six readiness questions and turn each no into a dated task.",["Run a blind test where a stranger plays from the written rules while you say nothing.","Photograph a full set of components and label each image as prototype, render or final.","Ask a manufacturer for a written quote on your smallest realistic print run.","Get a rough shipping cost for one copy to your main countries.","Name the people who will back you on day one and how you will reach them."],"Hypothetical example: you answer yes on the rules, the photos and the cover art, but you have no print quote and no shipping figure. So the next month goes on quotes, plus the 20 to 30 percent contingency Kickstarter suggests as a starting point. Meanwhile your prelaunch page can go live, so it gathers followers while the numbers come in.","Every no should have an owner and a date, and your launch date should come after the last of them."],
["board-game-kickstarter-cost","Build your two column launch budget this week.",["Make one column for costs you pay before launch and one for costs paid from pledges.","Put a number beside every before launch line: prototypes, art, reviewer copies, the page and marketing.","Mark any line you can't price yet as a question, and ask for the biggest quotes first.","In the second column, list manufacturing, shipping, customs, packaging, handling and fees.","Add a reserve, starting from the 20 to 30 percent Kickstarter suggests."],"Hypothetical example: 750 backers pledge $40 each on a US project, so the campaign raises $30,000. Fees take about $2,550 and a 20% reserve keeps back $6,000. That leaves about $21,450 to make, ship and deliver every game, so if your print and freight quotes come to more, the goal has to rise before you launch.","Every line in both columns should carry a number or a named question, and the second column should still balance at your exact funding goal."],
["when-to-launch-a-kickstarter","Check your three readiness signals, then work back from a real date.",["Estimate how much of your goal your email list could raise in the first 24 hours.","Show the preview to someone who hasn't played and ask them to explain the game back.","Confirm a manufacturer quote, a shipping estimate and a goal that covers fees and a reserve.","Write a real date beside each step of the backward plan, starting from the slowest job.","Check that month for conventions you're attending and big launches in your niche."],"Hypothetical example: you pick a Tuesday launch eight weeks away. Working back, reviewer copies need up to a month before a post appears, and review can take up to three business days plus three more for changes. If the reviewer step already lands in the past, the date is too early, and moving it now costs less than launching thin.","Every step in the backward plan should fit before launch day with a week to spare, and all three signals should be true."],
["why-kickstarter-campaigns-fail","Run the five failure checks on your campaign a few weeks before launch.",["Count the people already following the project and on your email list.","Show the page to five people who have never seen the game and ask them to explain it back.","Rebuild the goal from your smallest print run, freight, fulfillment, fees and a buffer.","Look at every photo, date and shipping note as a stranger deciding whether to trust you.","Write down why you chose the launch date, and move it if your readiness disagrees."],"Hypothetical example: three of your five testers can't say how a turn works, and your followers are mostly friends and family. Those are two of the causes this guide names, and both show before launch. Moving the date by a month with a short, honest update costs far less than a slow start, because the goal and deadline lock once you launch.","Answer each of the five questions with someone who will tell you the truth, and fix every shaky answer before you confirm the date."],
["kickstarter-for-beginners","Answer the beginner questions that apply to you before you plan a campaign.",["Check that you are 18 or older and live in a supported country, with ID and a bank account there.","Decide whether you launch as an individual or a business, and ask an accountant about tax.","Write down your goal, your campaign length and the fees on one typical pledge.","Mark when money could arrive: 14 days after the deadline, plus your bank's time.","List what you would owe backers if you fund, through to the last box arriving."],"Hypothetical example: your 30 day campaign ends on a Friday. Kickstarter spends 14 calendar days collecting and processing pledges, then your bank may take another 3 to 14 business days. So a manufacturer deposit due the week after your deadline needs other money, and that belongs in your plan now.","You should be able to explain to a friend, in your own words, what happens to backers' money if you fund and if you don't."],
["how-to-launch-a-board-game-on-kickstarter","Place your game on the launch timeline and find the first stage that isn't done.",["Write today's date and your hoped for launch date at the top of one page.","Mark each stage as done, started or not started: the game, the numbers, prelaunch, the page and review.","Build the budget before the goal, with fees, shipping and a reserve of 20 to 30 percent.","Put your prelaunch page and email signup live as soon as you can show the game.","Count back from launch, allowing up to three business days for review and three more for changes."],"Hypothetical example: your game is playtested and the cover art is done, but you have no manufacturer quote and no prelaunch page. On the example timeline, the numbers sit four to six months before launch and the prelaunch page three to four months before. So a launch eight weeks from now is too early, and this week's job is asking for quotes and opening the prelaunch page.","Every stage before your launch date should be marked done or have a date, and the goal should come from the budget rather than the reverse."],
["how-to-launch-a-kickstarter-campaign","Find the first stage of your Kickstarter launch that isn't done and give it a date this week.",["Confirm you live in a supported country and can verify ID, a local bank account and a card.","Run your idea through the fit questions: something new, a clear end point and rewards you made.","Build the budget before the goal, with production, shipping, fees, ads and a reserve.","Open an email signup page as soon as you can show a working prototype or sample.","Count back from launch: review four to six weeks out, then the prelaunch page after approval."],"Hypothetical example: you have a working prototype of a $49 product and one factory quote, but no shipping quote and no signup page. Shipping is stage seven and the signup page belongs to stage two, so a launch six weeks from now is too early. This week's job is a packed weight, two more quotes and a live signup page.","Every one of the ten stages is marked done or has a date, and your goal comes from the budget rather than the other way round."],
["kickstarter-campaign-timeline","Turn your launch date into a 12 week plan with one visible result due each week.",["Write your launch date at the top of a page and count back 12 weeks to find week 1.","Check the basics first: a working prototype, production quotes, a packed weight and eligibility.","Verify your Kickstarter account in week 1 and put the signup page live in week 2.","Mark the end of week 6 as the day you send the project to review.","Add the campaign end date, 14 days of pledge collection and a delivery month you can hit."],"Hypothetical example: you want to launch on Tuesday, April 13, 2027. Week 1 starts on January 19, the signup page goes live the week of January 26 and the project goes to review by March 1. Approval in early March opens the prelaunch page with about five weeks to collect followers before launch.","Every week from now to launch has a named result, and review is booked at least four weeks before launch day."],
["how-to-launch-a-product-on-kickstarter","Find the first launch stage your product hasn't finished and give it a date.",["Film your working prototype doing every main feature, with real hands in a real setting.","Ask two or three factories for written quotes with unit price, MOQ, tooling and lead time.","Build a budget from the minimum order, fees of about 8% plus $0.20 a pledge, fulfillment and a 20 to 30 percent reserve.","Get shipping quotes for your top five backer countries using the packed weight.","Put a signup page live with real photos and count signups each week."],"Hypothetical example: your prototype works and is filmed, but you only have one factory quote and no signup page. The MOQ in that quote is 500 units at $28 landed, so your goal has to cover $14,000 of production before fees and a reserve. This week's jobs are a second quote and a live signup page.","Every stage before your launch date is marked done or has a date, and the goal comes from the minimum order rather than a round number."],
["kickstarter-for-existing-products","Decide whether your new version counts as new, then plan how past buyers hear about it.",["List every change from version one in your customers' words, and cut anything that is only a new color.","Photograph version one and the version two prototype side by side.","Count your version one stock and choose to sell it down, bundle it as an add on or hold it.","Draft a Secret Reward for past buyers priced just below the early bird.","Write the first update to your old backers and the first email to customers who agreed to hear from you."],"Hypothetical example: version one sold at $45 and version two adds a new material and a better clasp, retailing at $69. You set an early bird at $49, a past buyer Secret Reward at $47 and a version one add on at $25. Your old backers get the prelaunch link three weeks before launch.","A stranger can say what changed from one photo, and your past buyer offer, add on and announcement dates are all written down."],
["kickstarter-reward-pricing-physical-products","Build one pricing sheet that runs every reward from landed cost to what you keep.",["Add up landed cost per unit: factory price, packaging, a share of tooling, freight and duties.","Add pick and pack, about 8% plus $0.20 in fees on a US pledge, a reserve and your ad cost per backer.","Set the future retail price, then place the Kickstarter price and a capped early bird below it.","Price a two pack and check it earns more per backer than a single unit.","Raise landed cost by 15% and confirm every tier still leaves money."],"Hypothetical example: your landed cost is $21, pick and pack is $3 and ads cost $8 per backer. A $59 Kickstarter price pays $4.92 in fees and a $4.20 reserve, leaving $17.88. A $49 early bird leaves $8.68, so you cap it rather than leave it open.","Every tier stays positive after a 15% cost rise, and each one shows its saving against the retail price."],
["tech-gadget-kickstarter-launch-guide","Find the first gap between your gadget and a launch you can deliver.",["Film the working prototype doing its main job in one continuous take.","Ask a factory to quote three quantities, with tooling and samples on separate lines.","Get a written FCC and CE test plan and price from a test lab.","Ask your cell maker for the UN 38.3 test summary and your fulfillment partner for a written yes on batteries.","Draft a delivery timeline with DVT, certification, PVT, freight and a buffer."],"Hypothetical example: your Bluetooth speaker works on the bench, but no factory has quoted it and you have not spoken to a test lab. The readiness check stops at the second question, so this week is for quote requests, not page design. Once three quotes and a lab plan are back, you can set a goal and a delivery month you can defend.","Every question in the readiness check has a yes, or a dated plan to get one."],
["kickstarter-prototype-rules","Check your page against Kickstarter's prototype rules before you submit it for review.",["Film the real prototype doing its core job and keep the clip on the page.","Replace every photorealistic render with a photo or a clearly illustrated drawing.","Label each prototype image with its stage.","Write the production section: maker, stage, steps left and your track record.","Answer the generative AI questions and say which parts, if any, used AI."],"Hypothetical example: your page opens with a lifelike render of a desk lamp because the final shell is not molded yet. Swap it for a photo of the working prototype with a stage label, and move a line drawing of the final shape further down. The page now shows proof first and the future design second.","No image on the page could be mistaken for a finished product that does not exist yet."],
["kickstarter-product-photography","Write a shot list from your page outline and brief your photographer with it.",["List every page section and the image it needs.","Add one photo or GIF for each feature you claim.","Mark which units are working prototypes and which are models.","Choose backgrounds and props that match your page design.","Check each shot against the list before you pack up the shoot."],"Hypothetical example: your page outline has eight sections and claims five features. That gives you eight section images and five feature proofs, two of them GIFs because they involve movement. Add a scale shot, a box layout and two lifestyle shots, and you have about eighteen shots for one shoot day.","Every section of your page outline has a named shot, and every feature claim has its proof."],
["manufacturing-quotes-before-kickstarter","Send one complete quote request to at least three factories.",["Put drawings, bill of materials, materials and packaging into one pack.","Ask for prices at your goal, expected and strong quantities.","Ask for tooling, samples and packaging on separate lines.","Ask where the price ends, such as EXW or FOB, and how long it is valid.","Turn the best quote into landed cost and a draft funding goal."],"Hypothetical example: one factory quotes $17.90 a unit with a 2,000 unit MOQ, and another quotes $18.20 with a 1,000 unit MOQ. With the first, your goal would have to fund 2,000 units, nearly double the stock. The second quote is the cheaper campaign even though its unit price is higher.","Your funding goal covers the full minimum order, tooling, samples, freight, a reserve and fees."],
["how-to-launch-a-book-on-kickstarter","Price your book campaign from real print and postage numbers this week.",["Ask two printers for quotes at two or three run sizes, offset and print on demand.","Order one proof copy and check color, paper and layout.","Weigh one packed copy of each format, mailer included.","List one ISBN for each format you will sell.","Name your first 25 likely backers and where you will reach them."],"Hypothetical example: your paperback costs $6 a copy on print on demand and weighs just under a pound packed. You plan a $25 signed paperback tier, so after fees, print and Media Mail postage you can see what each pledge leaves for editing and a reserve. If 25 backers at that tier would not cover the goal, you add an ebook tier and a limited hardcover before you launch.","Every reward tier should show its print cost, postage and fees, and the goal should still cover them at your expected backer count."],
["watch-fashion-accessories-kickstarter-guide","Turn your factory quote into options and rewards that clear every minimum.",["Get the MOQ per style and per color in writing.","Approve fit samples and photo samples in every color you plan to show.","Draft a size curve from your sales, waitlist or a follower poll.","List every material and sustainability claim with the document that proves it.","Write a returns and exchanges policy for size and for defects."],"Hypothetical example: your factory's MOQ is 300 units per color, and a poll suggests only 15% of followers want the third color. At 1,000 backers that color would sell about 150 units, half its minimum. So you launch with two colors and offer the third as a stretch goal that unlocks only if its orders clear 300.","Every color and size you offer should clear its minimum at your expected backer count, and every claim on the page should have a document on file."],
["creative-project-kickstarter-guide","Shape your idea into one Kickstarter project with a floor goal and a community ready to back it.",["Write the one thing you will make and the date it is finished.","Check that any charity share is 10% or less and that no reward pays money back.","List only the costs needed to finish and deliver, plus fees and a reserve.","Write down 30 people likely to back on day one and how you will reach them.","Pick a digital entry tier, one physical tier and one limited experience."],"Hypothetical example: your band wants to record an EP and press vinyl. The floor that finishes the record is $3,000, while a music video would push it to $6,000. You set the goal at $3,000, make the video a stretch goal, and check that 30 named fans at an average $40 pledge plus a $5 download tier could get you most of the way.","You can say in one sentence what backers get and when, and your first 30 backers could cover at least a third of the goal."],
["kickstarter-vs-indiegogo","Answer the four platform questions and write down which platform fits your product and why.",["Film your prototype working, or note the date it will be ready, because Kickstarter will not accept renders for hardware.","Write down how much of your stock is ready or close to ready to ship.","Estimate your average pledge and check whether most pledges will pass $125.","Put your factory deposit date beside the Kickstarter payout date, 14 days after the deadline plus your bank's time.","Ask your fulfillment partner which pledge manager they can import orders from."],"Hypothetical example: you make a $160 desk lamp with a working prototype and no stock yet. You need a goal to pay for the first run, most pledges will pass $125, and your factory deposit is due a month after launch. That points to Kickstarter with Pledge Over Time switched on, and a deposit date moved to after the payout lands.","You can explain your platform choice to a friend in two sentences, naming the rule or tool that decided it."],
["kickstarter-campaign-cost","Build your two budget Kickstarter cost sheet this week.",["Make one column for costs you pay before launch and one for costs paid from pledges.","Price samples, photos and video, page design, ads and tools in the first column, even if some are zero.","In the second column, list manufacturing, shipping by region, packaging, pledge manager fees, duties and taxes.","Add Kickstarter fees at 5% plus 3% and $0.20 a pledge, and a reserve of 20 to 30 percent.","Check that you could make and ship every reward at exactly 100% of the goal."],"Hypothetical example: 500 backers pledge $60 each on a US project, so the campaign raises $30,000. Fees take about $2,500 and a 20% reserve keeps back $6,000. That leaves $21,500 to make, pack and ship every reward, so if your quotes come to more, the goal rises before launch.","Every line in both columns carries a number or a dated question, and the goal covers the second column in full."],
["kickstarter-shipping-physical-products","Make your five shipping decisions and write each one into your campaign plan.",["Weigh and measure each reward boxed, including the heaviest likely add on combination.","Get written quotes from two fulfillment models for your top backer countries.","Decide whether you pay duties upfront or backers pay on delivery, and write it for the page.","Choose to charge shipping at pledge or later, and set the estimate range you will show.","Check the current US entry rules for parcels and the EU rules for orders of 150 euros or less."],"Hypothetical example: your boxed product weighs 900 grams and most backers are in the US, UK and Germany. A warehouse quote for the US and a direct quote for Europe come in, but neither is firm for next spring. So you charge shipping later, show an estimate range on the page, and say clearly that duties are paid before delivery.","Each reward has a shipping price or an estimate range for every country you serve, and the page says who pays duties."],
["relaunch-failed-kickstarter","Name the one main reason your campaign fell short and write the fix beside it.",["Export your dashboard numbers: page visits, referrers, pledges and dropped pledges.","Answer the four diagnosis questions: traffic, conversion, goal and price.","Post an honest update to backers with a signup link for the relaunch.","Rebuild the goal from what you need, not what you hoped to raise.","Set a relaunch date only once your list is clearly bigger than last time."],"Hypothetical example: your page had plenty of visits from your own email list, but few of them pledged and many dropped at checkout. That points to conversion, not traffic. So the relaunch starts with a new opening section, clearer photos and simpler tiers, and the date can come sooner than if you had to grow the list.","You can say in one sentence why the first campaign failed and what will be different on the relaunch page."],
["kickstarter-statistics-by-category","Find your category's real numbers and test your funding goal against them this week.",["Write down your category and its success rate from the table, with the period it covers.","Set your planned goal beside the funding brackets and note what share of successful projects raised more.","Count your likely day one backers from your email list and prelaunch followers.","Multiply that count by your expected average pledge and compare it with the goal.","Mark every statistic you plan to quote in your page or pitch with its source and date."],"Hypothetical example: you plan a $24,000 goal for a Design project with an expected $60 average pledge. That needs 400 backers, and it is more than about 80% of successful projects raised as of January 2025. You have 150 people on your list, so you either grow the audience before launch or lower the goal to what your costs truly need.","You can say in one sentence how your goal compares with your category and where the backers to reach it will come from."],
["crowdfunding-glossary","Learn the terms for the stage you are at and turn each one into a decision for your project.",["Pick the glossary group that matches where your project is today.","Read each term in that group and mark the ones that need a decision from you.","Write your answer beside each marked term, such as your goal, your tiers or your payout date.","Ask suppliers about MOQ, unit cost, lead time and landed cost in writing.","Open the linked guide for any term you still cannot answer in one sentence."],"Hypothetical example: you are building the page, so you work through the page and rewards group. You decide on three reward tiers, two add ons and one stretch goal, and you note that a hardware project needs a working prototype on film. Then you move to the money group and work out the fees on your main tier.","Every term in your current group has a written answer or a linked guide you will read next."],
["kickstarter-campaign-brief", "Put everything your campaign designer needs into one brief before the first call.", ["Write one sentence on what the product is and who it is for.", "Gather your best photos, renders and any video, each labelled as prototype, render or final.", "List every reward with its contents, price and estimated delivery month.", "Add your launch window, your funding goal and the platform you plan to use.", "Note what you already have, such as a logo, an email list or product copy, and what is still missing."], "Hypothetical example: a creator sends a strap prototype photo, a rough price and a target month. The designer can start, but only after a second round of questions about rewards, shipping regions and which photos are final. Sending those answers in the first brief saves about a week.", "Give the brief to someone who has never seen the product. If they can say what it is, who it is for and what a backer receives, it is ready to send."],
["product-kickstarter-page", "Outline your product page section by section before any design starts.", ["Write the top: project image, title and a subtitle a stranger understands.", "List the three problems the product solves and the proof for each, such as a test or a photo.", "Plan the reward section so every option can be compared side by side.", "Add the facts backers check before pledging: specifications, materials, delivery dates and shipping regions.", "Write the risks and challenges section in plain words."], "Hypothetical example: a page opens with lifestyle photos but only explains what the product does halfway down. Moving one clear photo of the product in use and a short line of what it does to the top answers the first question a visitor has.", "Show the outline to a stranger on a phone. If they can say what the product is and what they would pledge for within a minute, the outline works."],
["kickstarter-funding-goal", "Set a goal you could deliver on if the campaign ended exactly on target.", ["Add the cost of making and shipping every reward at the goal itself.", "Include the factory minimum order, tooling and any certification.", "Add platform and payment fees at your country's current rates.", "Add a buffer for surprises, then round up to a clear number.", "Check that the goal still delivers if most backers choose the cheapest reward."], "Hypothetical example: a creator needs $20,000 to cover a minimum order, shipping and fees, so the goal is set at $22,000 with a buffer. A lower goal would look easier to reach but would leave them short if the campaign ended on target.", "If the campaign ends exactly at the goal, every reward can still be made and shipped without money you do not have."],
];
export const guideWorkbooks: Record<string, GuideWorkbook> = Object.fromEntries(entries.map(([slug,goal,actions,example,check])=>[slug,{goal,actions,example,check}]));
